import type { ReactNode } from "react";

/** Concentric rings that swell outward from the centre, as a calm backdrop behind a heading or a call to action. Content goes in front of the rings. */
export interface RippleSpecProps {
  /**
   * Content shown in front of the rings, centred.
   */
  children?: ReactNode;
  /**
   * Diameter in pixels of the innermost ring.
   * @default 210
   */
  size?: number;
  /**
   * How many rings, 1 to 12.
   * @default 6
   */
  rings?: number;
  /**
   * Seconds for one swell.
   * @default 4
   */
  duration?: number;
  /**
   * Colour of the rings, any CSS colour. Defaults to the strong border colour.
   */
  color?: string;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Classes for the wrapper: size it and give it a background.
   */
  className?: string;
}

export const rippleDefaults = {
  size: 210,
  rings: 6,
  duration: 4,
  isPaused: false,
} as const;

export const rippleMeta = {
  "name": "Ripple",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
